         };
         match op {
             DispatchOp::NoteOn {
                 target,
                 note,
                 velocity,
                 channel,
             } => {
                 let first_owner = count_routed_note_on(
                     output_notes,
                     routed_note_key(*target, *channel, *note, mix_group),
                 );
