  1070	
  1071			// Apply each setting independently so one failure doesn't block the rest
  1072			const ops: [string, () => Promise<void>][] = [
  1073				['key', () => adapter.setKey(saved.key)],
  1074				['mode', () => adapter.setMode(saved.mode)],
  1075				['scaleMode', () => adapter.setScaleMode(saved.scaleMode)],
