 69	fn discard_if_overflow<C>(overflow: &AtomicBool, audio_rx: &mut C) -> bool
 70	where
 71	    C: Consumer<Item = f32>,
 72	{
 73	    if !overflow.swap(false, Ordering::AcqRel) {
 74	        return false;
 75	    }
 76	    while audio_rx.try_pop().is_some() {}
 77	    true
 78	}
